import { Router } from "express";

import { pool } from "../db";

export const cancelRouter = Router();

cancelRouter.post("/orders/:id/cancel", async (req, res) => {
  const found = await pool.query("SELECT id FROM orders WHERE id = $1", [
    req.params.id,
  ]);
  if (found.rowCount === 0) {
    res.status(404).json({ error: "no such order" });
    return;
  }
  await pool.query(
    "UPDATE orders SET cancelled_at = now(), status = 'cancelled' WHERE id = $1",
    [req.params.id],
  );
  res.status(200).json({ id: req.params.id, status: "cancelled" });
});

